import{_ as t,o,c as a,a3 as n}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"Account and sign-in","description":"Creating an account, signing in, resetting your password, profile, and deleting your account.","frontmatter":{"title":"Account and sign-in","description":"Creating an account, signing in, resetting your password, profile, and deleting your account."},"headers":[],"relativePath":"en/erste-schritte/konto-und-anmeldung.md","filePath":"en/erste-schritte/konto-und-anmeldung.md","lastUpdated":1788446198000}'),r={name:"en/erste-schritte/konto-und-anmeldung.md"};function s(i,e,l,c,p,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="account-and-sign-in" tabindex="-1">Account and sign-in <a class="header-anchor" href="#account-and-sign-in" aria-label="Permalink to &quot;Account and sign-in&quot;">​</a></h1><h2 id="creating-an-account" tabindex="-1">Creating an account <a class="header-anchor" href="#creating-an-account" aria-label="Permalink to &quot;Creating an account&quot;">​</a></h2><p>Open <a href="https://app.apptivegrid.de" target="_blank" rel="noreferrer">app.apptivegrid.de</a>. If you&#39;re not signed in, you land on the login page, where <strong>Sign up</strong> next to <em>Don&#39;t have a account?</em> takes you further:</p><blockquote><p><strong>Create an account</strong><em>Sign up - no credit card needed.</em></p></blockquote><p>There are two routes:</p><p><strong>With an existing account</strong> — <strong>Sign up with Google</strong>, <strong>Sign up with Apple</strong>, or <strong>Sign up with Microsoft</strong>. You don&#39;t set a password of your own.</p><p><strong>With email and password</strong> — enter your <strong>Email</strong>, add <strong>First name</strong>, <strong>Last Name</strong>, and <strong>Password</strong>, and confirm with <strong>Sign up</strong>.</p><p>Validation reports <em>Required</em>, <em>Min 3 characters</em>, <em>Use at least 8 characters</em>, and <em>Please enter a valid email</em>. If account creation fails:</p><blockquote><p><em>We were unable to create an account with the email and password you entered. Please check your email and password and try again.</em></p></blockquote><p>The message doesn&#39;t name the reason. So also check whether an <strong>account already exists</strong> for that address — in which case <a href="#forgot-password">Forgot password</a> is the way forward.</p><div class="tip custom-block"><p class="custom-block-title">What the password has to meet</p><p>At least 8 characters and at most 128 — otherwise the form reports <em>Use at least 8 characters</em> or <em>Use at most 128 characters</em>. Capitals, digits, and symbols aren&#39;t required; length protects better than a forced mix. Still pick one you use nowhere else — every Space you build will hang off this account.</p></div><p>Creating the account means accepting the contract terms:</p><blockquote><p><em>By clicking &quot;Sign up&quot;, you agree to ApptiveGrid&#39;s Terms of Service, Privacy Policy and Vendor Data Processing Addendum.</em></p></blockquote><h3 id="confirming-your-email" tabindex="-1">Confirming your email <a class="header-anchor" href="#confirming-your-email" aria-label="Permalink to &quot;Confirming your email&quot;">​</a></h3><p>After you submit:</p><blockquote><p><strong>Account created!</strong><em>Please check your email. You will receive an email with a confirmation link.</em></p></blockquote><p>The link in that email activates the account:</p><blockquote><p><strong>Welcome to ApptiveGrid</strong><em>Your account is ready.</em></p></blockquote><p><strong>Open ApptiveGrid</strong> takes you to the sign-in page.</p><div class="tip custom-block"><p class="custom-block-title">No email arriving?</p><p>Check your spam folder. The Google, Apple, and Microsoft routes skip this step — there, the provider confirms the address.</p></div><div class="warning custom-block"><p class="custom-block-title">You can&#39;t link to the sign-up page</p><p>It&#39;s part of a single sign-in process and can&#39;t be passed around as an address of its own. Anyone who should register gets pointed to <strong>app.apptivegrid.de</strong> and clicks <strong>Sign up</strong> there.</p><p>If people are meant to join a particular Space, an <a href="/en/zusammenarbeit/personen-einladen">invitation</a> is the better route: the link in the invitation email leads through registration and straight into the Space.</p></div><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Sign-in happens on its own page, not inside the application:</p><blockquote><p><strong>Login to your account</strong><em>Welcome back!</em></p></blockquote><p>Either through <strong>Continue with Google</strong>, <strong>Continue with Apple</strong>, and <strong>Continue with Microsoft</strong> — or with <strong>Email</strong> and <strong>Password</strong>.</p><p>If the details are wrong:</p><blockquote><p><strong>Login failed</strong><em>We were unable to log you in. Please check your email address and password.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Always take the same route</p><p>An account created through Google, Apple, or Microsoft has no password of its own at ApptiveGrid. Sign in later using the same button you used to create the account.</p></div><div class="tip custom-block"><p class="custom-block-title">No account needed for forms</p><p>Anyone who&#39;s just filling out a <a href="/en/formulare/formular-erstellen">form</a> or viewing a <a href="/en/seiten/portal-veroeffentlichen">portal</a> needs <strong>no</strong> ApptiveGrid account — unless access has been explicitly restricted.</p><p>You only need an account once you want to build Grids, Forms, Flows, or Pages yourself.</p></div><h3 id="signing-in-with-microsoft" tabindex="-1">Signing in with Microsoft <a class="header-anchor" href="#signing-in-with-microsoft" aria-label="Permalink to &quot;Signing in with Microsoft&quot;">​</a></h3><p>For work and school accounts, your own organization&#39;s IT decides which external applications may sign people in. If that is restricted, <strong>Continue with Microsoft</strong> may stop with <em>Approval required</em>. Nothing is wrong with your account — an approval is missing in Microsoft Entra.</p><p>A page of its own, <a href="/en/erste-schritte/anmeldung-mit-microsoft">Signing in with Microsoft</a>, covers both sides: what you do yourself, and what your IT department has to clear. It&#39;s written to be passed on.</p><h3 id="session-expired" tabindex="-1">Session expired <a class="header-anchor" href="#session-expired" aria-label="Permalink to &quot;Session expired&quot;">​</a></h3><blockquote><p><strong>Session expired</strong><em>Your sign-in has expired or could not be completed.</em></p></blockquote><p>The login page belongs to one single sign-in process. The message appears in two cases:</p><ul><li>The page was <strong>opened directly</strong>, for instance from a bookmark pointing at the login page itself.</li><li>The page sat <strong>open for more than half an hour</strong>.</li></ul><p><strong>Sign in again</strong> restarts the process.</p><div class="tip custom-block"><p class="custom-block-title">Bookmark app.apptivegrid.de</p><p>Not the login page. A bookmark on the login page carries an expired process along with it and leads to exactly this message.</p></div><p>If sign-in fails for a different reason, ApptiveGrid gives the same recommendation and points to <strong><a href="mailto:support@apptivegrid.de" target="_blank" rel="noreferrer">support@apptivegrid.de</a></strong>. That address sits at the bottom left of every page of the sign-in flow.</p><h2 id="forgot-password" tabindex="-1">Forgot password <a class="header-anchor" href="#forgot-password" aria-label="Permalink to &quot;Forgot password&quot;">​</a></h2><p>On the login page, <strong>Forgot password</strong> takes you further:</p><blockquote><p><strong>Forgot password</strong><em>No worries, we&#39;ll send you instructions.</em></p></blockquote><p>You enter your <strong>Email</strong> and confirm with <strong>Reset Password</strong>. Then:</p><blockquote><p><strong>Check your email</strong><em>We sent a password reset link.</em></p></blockquote><p>If nothing arrives, <em>Didn&#39;t receive the email?</em> → <strong>Resend email</strong> helps. <strong>Back to login</strong> returns to sign-in.</p><p>The link in the email leads to:</p><blockquote><p><strong>Set Password</strong><em>Choose a new password</em></p></blockquote><p>The same limits apply as when signing up: at least 8 characters, at most 128.</p><p><strong>Set password</strong> saves it:</p><blockquote><p><strong>Updated your Password</strong><em>Your are ready to log in.</em></p></blockquote><div class="danger custom-block"><p class="custom-block-title">Don&#39;t forward that link</p><p>It carries a token that lets anyone set the password without further checks. Whoever holds the link gets into your account.</p></div><div class="warning custom-block"><p class="custom-block-title">This doesn&#39;t apply to password-protected links</p><p>The username and password of a protected <a href="/en/zusammenarbeit/zugriff-beschraenken#views-and-portals-username-and-password">view or page</a> aren&#39;t ApptiveGrid accounts. They can&#39;t be reset here — only reissued by whoever created the link.</p></div><h2 id="on-first-launch" tabindex="-1">On first launch <a class="header-anchor" href="#on-first-launch" aria-label="Permalink to &quot;On first launch&quot;">​</a></h2><p>After your first sign-in, ApptiveGrid asks:</p><blockquote><p><em>What will you be using ApptiveGrid for?</em></p></blockquote><p>You can choose <strong>Personal</strong>, <strong>Work</strong>, or <strong>Other</strong>.</p><p>After that, the Space overview greets you — depending on the time of day, with <em>Good morning</em>, <em>Hello</em>, <em>Welcome</em>, or <em>Good evening</em>.</p><h2 id="checking-who-s-signed-in" tabindex="-1">Checking who&#39;s signed in <a class="header-anchor" href="#checking-who-s-signed-in" aria-label="Permalink to &quot;Checking who&#39;s signed in&quot;">​</a></h2><p>On shared devices, someone else may already be signed in. ApptiveGrid flags this:</p><blockquote><p><em>You are signed in as {email}.</em><em>Please only continue if this is your own account.</em></p></blockquote><p>Confirm with <strong>Yes, I am {name} - continue</strong>, or switch with <strong>Use another account</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Same check for forms and pages</p><p><a href="/en/formulare/formular-erstellen">Forms</a> and <a href="/en/seiten/seitenlayout">pages</a> have the setting <em>Confirm correct account</em> or <em>Show account confirmation notice</em>, respectively.</p><p>This is worth using for applications on shared workshop, reception, or training-room computers — otherwise entries get submitted under someone else&#39;s name.</p></div><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>Under <strong>Profile &amp; settings</strong> → <strong>Profile</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th></th></tr></thead><tbody><tr><td><strong>Profile picture</strong></td><td>Your picture</td></tr><tr><td><strong>First name</strong>, <strong>Last name</strong></td><td>The name shown to others</td></tr><tr><td><strong>Email</strong></td><td>Your address</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Profile pictures have a size limit</p><p><em>Choose an image in jpg format.</em> and <em>The file is too large. Choose an image smaller than 1MB.</em></p></div><p>Your name appears in the <strong>Created by</strong> column and in the <a href="/en/grids/versionsverlauf">version history</a> — visible to other people in the Space.</p><h2 id="account-settings-vs-space-settings" tabindex="-1">Account settings vs. Space settings <a class="header-anchor" href="#account-settings-vs-space-settings" aria-label="Permalink to &quot;Account settings vs. Space settings&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">A common mix-up</p><table tabindex="0"><thead><tr><th>Area</th><th>Applies to</th></tr></thead><tbody><tr><td><strong>Profile &amp; settings</strong></td><td>You personally — profile, billing, API credentials</td></tr><tr><td><strong>Space settings</strong></td><td>One Space — plan, seats, webhooks, links</td></tr></tbody></table><p>The plan is booked per <strong>Space</strong>, but the payment details are tied to the <strong>account</strong>.</p></div><p>→ <a href="/en/spaces/einstellungen">Space settings</a></p><h2 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h2><p>Under <strong>Billing</strong>:</p><blockquote><p><em>Manage subscriptions, download invoices, and update payment or billing details</em></p></blockquote><p>The <strong>Invoices and subscription</strong> button takes you to the payment provider.</p><h2 id="api-credentials" tabindex="-1">API Credentials <a class="header-anchor" href="#api-credentials" aria-label="Permalink to &quot;API Credentials&quot;">​</a></h2><p>Under <strong>API Credentials</strong> you generate keys for accessing the programming interface.</p><div class="danger custom-block"><p class="custom-block-title">Personal and far-reaching</p><blockquote><p><em>Your personal API credentials grant access to all data in your Spaces. Only share these credentials with third-party services and applications you trust.</em></p></blockquote></div><p>→ <a href="/en/integrationen/api-zugangsdaten">API Credentials</a></p><h2 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h2><p>Under <strong>Help &amp; Support</strong>:</p><table tabindex="0"><thead><tr><th>Item</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Help Center</strong></td><td>Documentation</td></tr><tr><td><strong>Chat with us</strong></td><td>Direct contact with support</td></tr><tr><td><strong>Send us feedback</strong></td><td>Product feedback</td></tr><tr><td><strong>What&#39;s new?</strong></td><td>Latest updates</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Chat is the fastest route</p><p>For questions this documentation doesn&#39;t answer — like setting up an integration or plan details — chat connects you directly to support.</p></div><p>If a notice about a new app version appears, reload the page.</p><h2 id="preview-features" tabindex="-1">Preview features <a class="header-anchor" href="#preview-features" aria-label="Permalink to &quot;Preview features&quot;">​</a></h2><p>The profile has a toggle labeled <em>Try our latest features</em>.</p><div class="warning custom-block"><p class="custom-block-title">For experimentation only</p><p>This makes features that are still in development visible. They may change or disappear again.</p><p>Don&#39;t rely on them in guides for your team, and leave the toggle off in production use.</p></div><h2 id="deleting-your-account" tabindex="-1">Deleting your account <a class="header-anchor" href="#deleting-your-account" aria-label="Permalink to &quot;Deleting your account&quot;">​</a></h2><p>Under <strong>Profile</strong> → <strong>Delete account</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Permanent</p><blockquote><p><em>Your account and all data will be permanently deleted. Type DELETE into the text field to continue.</em></p></blockquote><p>You must type <code>DELETE</code> to confirm. There&#39;s no way to undo it.</p><p><strong>Check first:</strong> are you the owner of Spaces that others still need? Transfer them beforehand, or back up the data with a <a href="/en/grids/csv-export">CSV export</a>.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/erste-schritte/was-ist-apptivegrid">What is ApptiveGrid</a></li><li><a href="/en/erste-schritte/oberflaeche">The interface at a glance</a></li><li><a href="/en/zusammenarbeit/rollen">Roles</a></li></ul>',91)])])}const u=t(r,[["render",s]]);export{h as __pageData,u as default};
